; ############################################################################
; MAP-DATA BANK  —  bank 42 ($2A):  compressed TILEMAPS + TILESETS  (47 blocks)
; ############################################################################
; This bank is NOT code (the old 'Bank42_Fn0..Fn46' disassembly was a mislabel:
; the '$4001 function table' is really the LZ tile-block POINTER TABLE, and
; disassembling the compressed payload yields garbage). It holds the overworld/
; interior MAP data for several areas, as LZ blocks (TileLoad $18A2 format:
; each block = [count.w][escape][stream]). Two block KINDS, interleaved in groups:
;
;   * TILESET  (2048 B = 128 tiles, 2bpp) — the 8x8 pixel patterns -> VRAM $8000.
;     GFX blocks: $00, $08, $14, $21  (one per map group).
;   * TILEMAP  (512 B = a 32x16 grid of 8-bit tile numbers) -> WRAM $C300.
;     Each references the tileset of its group (the preceding GFX block).
;
; A room picks its {bank,block} via bank11 $4239 (AreaDir->room->variant). E.g.
; AREA 0 rooms all live here (tileset = block $00):
;   block $01 = area0 room0   block $05 = area0 room1   block $07 = area0 room5
; To view:  python3 tools/rendertiles.py 42 <block>       (tileset blocks)
;   or decode a tilemap:  rendertiles.decompress(data,42,<block>,base=0xC300)
; and composite tile#-> tileset (see chat: 'logic to draw the map').
; Verified: rendertiles.py --detect flags bank42 as TILE DATA (block counts %16).
; ############################################################################

SECTION "Bank 42", ROMX[$4000], BANK[42]

    db $2A                              ; $4000  self-ID (bank number)

; --- $4001 : LZ tile-block POINTER TABLE (47 entries, little-endian) ---
; each dw = in-bank address of a compressed block; annotated with decoded kind.
Bank42_BlockPtrs:                       ; $4001
    dw $405F                            ; block $00: TILESET  128 tiles
    dw $462C                            ; block $01: tilemap  32x16  <- area0 room0
    dw $46FE                            ; block $02: tilemap  32x16
    dw $47D0                            ; block $03: tilemap  32x16
    dw $48A2                            ; block $04: tilemap  32x16
    dw $4974                            ; block $05: tilemap  32x16  <- area0 room1
    dw $4A16                            ; block $06: tilemap  32x16
    dw $4AC4                            ; block $07: tilemap  32x16  <- area0 room5
    dw $4B46                            ; block $08: TILESET  128 tiles
    dw $522B                            ; block $09: tilemap  32x16
    dw $5387                            ; block $0A: tilemap  32x16
    dw $54B6                            ; block $0B: tilemap  32x16
    dw $55E2                            ; block $0C: tilemap  32x16
    dw $56EA                            ; block $0D: tilemap  32x16
